// @vitest-environment jsdom
/**
 * The page, and the catalogue behind it.
 *
 * The catalogue is generated by tools/licenses.py rather than written here, which
 * is the point of it — but it also means the page and its data can drift apart
 * without anyone editing either. A licence a package claims and the catalogue has no
 * text for is a notice we are failing to reproduce, and a build tool that sneaks
 * into the list is a claim about what ships that is not true.
 */
import { cleanup, fireEvent, render, screen, within } from "@testing-library/react";
import { afterEach, describe, expect, it } from "vitest";
import catalogue from "@/data/licenses.json";
import LicensesPage from "./LicensesPage";
import { t } from "@/i18n";

interface Entry {
  part: string;
  name: string;
  version: string;
  license: string;
  url: string;
  copyright?: string;
}

const data = catalogue as unknown as {
  parts: string[];
  licenses: Record<string, { name: string; text: string }>;
  packages: Entry[];
};

const rows = () => [...document.querySelectorAll<HTMLElement>("[data-package]")];

afterEach(cleanup);

describe("the licence catalogue", () => {
  it("has the text of every licence a package is under", () => {
    const missing = data.packages.filter((p) => !data.licenses[p.license]?.text.trim());
    expect(missing.map((p) => `${p.name} (${p.license})`)).toEqual([]);
  });

  it("gives every package a name, a version and somewhere to read more", () => {
    for (const p of data.packages) {
      expect([p.name, p.version === "", p.url.startsWith("https://")], p.name).toEqual([p.name, false, true]);
      expect(data.parts, p.name).toContain(p.part);
    }
  });

  it("keeps one copy of a licence rather than one per package", () => {
    // Every MIT package shares a text, so the file stays a hundred kilobytes rather
    // than becoming a megabyte of the same paragraph with different names in it.
    const texts = new Set(Object.values(data.licenses).map((l) => l.text));
    // one text per licence, however many packages share it
    expect(texts.size).toBe(Object.keys(data.licenses).length);
    expect(texts.size).toBeLessThan(data.packages.length / 5);
  });

  it("carries each package's own copyright instead of somebody else's", () => {
    // The shared text has the notices taken out of it. One left behind would be shown
    // under every other package on the same licence, which is how Facebook's name
    // ends up on somebody's weekend project.
    const notices = new Set(data.packages.flatMap((p) => (p.copyright ?? "").split("\n")).filter(Boolean));
    for (const [id, licence] of Object.entries(data.licenses)) {
      expect([id, [...notices].filter((n) => licence.text.includes(n))]).toEqual([id, []]);
    }
    // And where a package ships a licence file, the notice in it came along: every
    // Go module does.
    expect(data.packages.filter((p) => p.part === "server" && !p.copyright)).toEqual([]);
  });

  it("leaves out the tools that never reach anyone", () => {
    const names = new Set(data.packages.map((p) => p.name));
    for (const tool of ["vite", "vitest", "typescript", "esbuild", "electron", "electron-builder", "jsdom", "@types/react", "github.com/alicebob/miniredis/v2"]) {
      expect([tool, names.has(tool)]).toEqual([tool, false]);
    }
    // ... while the things that do are all there
    for (const shipped of ["react", "tauri", "tokio-tungstenite", "golang.org/x/crypto"]) {
      expect([shipped, names.has(shipped)]).toEqual([shipped, true]);
    }
  });
});

describe("LicensesPage", () => {
  it("lists every package, and narrows to what is searched for", () => {
    render(<LicensesPage />);
    expect(rows()).toHaveLength(data.packages.length);
    fireEvent.change(screen.getByTestId("licenses-search"), { target: { value: "react-dom" } });
    expect(rows().map((r) => r.dataset["package"])).toEqual(["react-dom"]);
    fireEvent.change(screen.getByTestId("licenses-search"), { target: { value: "no such package" } });
    expect(rows()).toEqual([]);
  });

  it("narrows to one build when a part is picked", () => {
    render(<LicensesPage />);
    // by the key's English, since the catalogue now has one: the filters are
    // named by `t()` and this was written before those strings existed
    fireEvent.click(screen.getByText(t("settings.licenses.server"), { selector: "button" }));
    expect(rows()).toHaveLength(data.packages.filter((p) => p.part === "server").length);
  });

  it("shows a licence when its package is opened, and only one at a time", () => {
    render(<LicensesPage />);
    const open = (name: string) => fireEvent.click(rows().find((r) => r.dataset["package"] === name)!);
    open("react");
    // Nexa's own MIT notice is always visible; check the opened package's
    // notice without confusing it with the application's licence.
    const detail = rows().find((r) => r.dataset["package"] === "react")!.parentElement!;
    expect(within(detail).getByText(/Permission is hereby granted/)).toBeTruthy();
    expect(screen.getByText(/Copyright \(c\) Facebook/)).toBeTruthy();
    open("zustand");
    expect(screen.queryByText(/Copyright \(c\) Facebook/)).toBeNull();
    expect(screen.getByText(/Copyright \(c\) 2019 Paul Henschel/)).toBeTruthy();
  });
});
